UPDATE public.lesson_scenes SET german_text = 'Ich gehe heute Abend mit einem Freund ins Restaurant.', translations = '{"bks":"Danas navečer idem s prijateljem u restoran.","tr":"Bu akşam bir arkadaşımla restorana gidiyorum.","uk":"Сьогодні ввечері я йду в ресторан з другом.","ro":"În seara asta merg la restaurant cu un prieten.","ar":"سأذهب مساء اليوم مع صديق إلى المطعم."}'::jsonb WHERE id = '42f28e1c-203a-45a7-99f7-1e31c4199662';

UPDATE public.lesson_scenes SET german_text = 'Wir haben einen Tisch reserviert.', translations = '{"bks":"Rezervisali smo sto.","tr":"Bir masa rezervasyonu yaptık.","uk":"Ми забронювали столик.","ro":"Am rezervat o masă.","ar":"لقد حجزنا طاولة."}'::jsonb WHERE id = 'ef4a5025-9c32-45a1-836f-83fcd0ab738f';

UPDATE public.lesson_scenes SET german_text = 'Der Kellner begrüßt uns freundlich.', translations = '{"bks":"Konobar nas ljubazno pozdravlja.","tr":"Garson bizi nazikçe karşılıyor.","uk":"Офіціант привітно вітає нас.","ro":"Chelnerul ne întâmpină prietenos.","ar":"يرحب بنا النادل بلطف."}'::jsonb WHERE id = '54058b93-7e9e-4560-8373-7494c4c80719';

UPDATE public.lesson_scenes SET german_text = 'Er zeigt uns unseren Tisch und bringt die Speisekarte.', translations = '{"bks":"Pokazuje nam naš sto i donosi jelovnik.","tr":"Bize masamızı gösteriyor ve menüyü getiriyor.","uk":"Він показує нам наш столик і приносить меню.","ro":"Ne arată masa și aduce meniul.","ar":"يُرينا طاولتنا ويحضر قائمة الطعام."}'::jsonb WHERE id = 'be92767f-f884-4286-90fe-bbcd2f4775c8';

UPDATE public.lesson_scenes SET german_text = 'Ich schaue mir die Speisekarte an.', translations = '{"bks":"Gledam jelovnik.","tr":"Menüye bakıyorum.","uk":"Я дивлюся на меню.","ro":"Mă uit pe meniu.","ar":"أنظر إلى قائمة الطعام."}'::jsonb WHERE id = '48e0955c-fb59-41d3-a906-5065c9a2c781';

UPDATE public.lesson_scenes SET german_text = 'Ich frage den Kellner nach einer Empfehlung.', translations = '{"bks":"Pitam konobara za preporuku.","tr":"Garsona bir öneri soruyorum.","uk":"Я питаю офіціанта про рекомендацію.","ro":"Îl întreb pe chelner ce recomandă.","ar":"أسأل النادل عن توصية."}'::jsonb WHERE id = '97f0fd64-ff73-4038-bbde-f695b095d7bc';

UPDATE public.lesson_scenes SET german_text = 'Er empfiehlt mir die Suppe des Tages.', translations = '{"bks":"Preporučuje mi dnevnu supu.","tr":"Bana günün çorbasını öneriyor.","uk":"Він рекомендує мені суп дня.","ro":"Îmi recomandă supa zilei.","ar":"يوصيني بشوربة اليوم."}'::jsonb WHERE id = '36b2c96e-f0f9-4cbb-883f-67c997f14861';

UPDATE public.lesson_scenes SET german_text = 'Ich bestelle die Suppe und einen Salat.', translations = '{"bks":"Naručujem supu i salatu.","tr":"Çorba ve salata sipariş ediyorum.","uk":"Я замовляю суп і салат.","ro":"Comand supa și o salată.","ar":"أطلب الشوربة وسلطة."}'::jsonb WHERE id = '59d90cd3-a5a8-41c7-9c2a-541b93c414a6';

UPDATE public.lesson_scenes SET german_text = 'Ich bestelle dazu ein Wasser.', translations = '{"bks":"Uz to naručujem vodu.","tr":"Yanına bir de su ısmarlıyorum.","uk":"До цього я замовляю воду.","ro":"Mai comand și o apă.","ar":"أطلب أيضًا ماءً."}'::jsonb WHERE id = '161b1d93-62d5-4432-853c-b9c1fb6d5e97';

UPDATE public.lesson_scenes SET german_text = 'Das Essen kommt und schmeckt sehr gut.', translations = '{"bks":"Hrana stiže i jako je ukusna.","tr":"Yemek geliyor ve çok lezzetli.","uk":"Їжа приходить і дуже смачна.","ro":"Mâncarea vine și este foarte gustoasă.","ar":"يأتي الطعام ويكون لذيذًا جدًا."}'::jsonb WHERE id = '8363ac98-706b-47e3-a7cb-173ffdbfba39';

