UPDATE public.lesson_scenes SET german_text = 'Der Kellner wünscht uns einen schönen Abend.', translations = '{"bks":"Konobar nam želi prijatno veče.","tr":"Garson bize iyi akşamlar diliyor.","uk":"Офіціант бажає нам гарного вечора.","ro":"Chelnerul ne urează o seară plăcută.","ar":"يتمنى لنا النادل مساءً سعيدًا."}'::jsonb WHERE id = '6d21731b-422c-4eaa-bea4-b3e9105ebb9c';

