UPDATE public.lesson_scenes SET german_text = 'Gerne. Bis wann muss die Aufgabe fertig sein?', translations = '{"bks":"Nema na čemu. Do kada zadatak mora biti gotov?","tr":"Rica ederim. Görev ne zamana kadar bitmiş olmalı?","uk":"Будь ласка. До якого часу завдання має бути готове?","ro":"Cu plăcere. Până când trebuie să fie gata sarcina?","ar":"عفوًا. متى يجب أن تكون المهمة جاهزة؟"}'::jsonb WHERE id = 'e38cc7a6-f0ba-4ca3-b616-e5be4e3516cc';